49	static inline vint32m2_t vd4dots_m2(vint32m2_t acc, vint8m2_t w, vint8m2_t a) {
50	    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
51	                 "nds.vd4dots.vv %0, %1, %2"
