file.content:
#pragma once

// andesim ROI node selection for the Q1_0 shape sweep (opt_roadmap F7).
//
// `andesim run --mode hybrid` reports cycle-accurate numbers for the code
// between andesim_ROI_begin/end. ggml executes a whole graph in one shot, so
// the only way to isolate one matmul is to count GGML_OP_MUL_MAT nodes in the
// dispatch loop and bracket node #K (see ggml-cpu.c). Which node that is comes
// from the build default -DANDESIM_ROI_MUL_MAT_K, overridable at run time so
// one binary can measure every shape in the model.
//
// Pure, host-testable (tests/test-roi-node.cpp); the markers themselves are
// RISC-V inline asm and live in ggml-cpu.c behind the same -D.

// Node index from an env string, or `fallback` when it is unset or not a node
// index. Strict on purpose: nodes are 1-indexed and a mis-parsed index measures
// the wrong matmul, which only shows up after hours of RTL simulation.
static inline int ggml_roi_node_index(const char * env_val, int fallback) {
    if (!env_val) {
        return fallback;
    }
    int n = 0;
    for (const char * p = env_val; *p; ++p) {
        if (*p < '0' || *p > '9') {
            return fallback;   // whitespace, sign, trailing junk
        }
        n = n * 10 + (*p - '0');
    }
    return n > 0 ? n : fallback;   // "" and "0" both land here
}

// Unit test for the andesim ROI node selector (opt_roadmap F7: per-shape cycle
// measurement).
//
// The ROI brackets MUL_MAT node #K so `andesim run --mode hybrid` can report
// cycle-accurate numbers for one matmul. K used to be a compile-time -D, which
// meant one rebuild per measured node. Bonsai-4B has 6 distinct Q1_0 GEMV
// shapes, so a shape sweep needs the node index chosen at run time instead.
//
// A wrong index silently measures the wrong matmul and wastes hours of RTL
// simulation, so parsing is strict: the whole string must be a positive
// integer (nodes are 1-indexed), anything else falls back to the build default.

#include "../ggml/src/ggml-cpu/roi.h"

#include <cstdio>

static int failures = 0;
#define CHECK(cond)                                                        \
    do {                                                                   \
        if (!(cond)) {                                                     \
            printf("FAIL line %d: %s\n", __LINE__, #cond);                 \
            ++failures;                                                    \
        }                                                                  \
    } while (0)

int main(void) {
    const int DEFAULT_K = 51;  // the shipped -DANDESIM_ROI_MUL_MAT_K

    // unset / empty env => keep the build default
    CHECK(ggml_roi_node_index(NULL, DEFAULT_K) == DEFAULT_K);
    CHECK(ggml_roi_node_index("", DEFAULT_K) == DEFAULT_K);

    // a valid index overrides it -- the four Bonsai-4B shapes to sweep
    CHECK(ggml_roi_node_index("50", DEFAULT_K) == 50);    // blk.7.attn_q
    CHECK(ggml_roi_node_index("53", DEFAULT_K) == 53);    // blk.7.attn_output
    CHECK(ggml_roi_node_index("54", DEFAULT_K) == 54);    // blk.7.ffn_gate
