1776	// ---- Q1_D4: the same row-parallel gemv on nds.vd4dots.vv (XAndesVDot) ------
1777	// Needs the Q1_D4 sign-plane order (repack.h q1_0x64_sign_bit) and
1778	// -march=..._xandesvdot. Only the VLEN>=1024 shape is implemented: e32/m2 is
1779	// then exactly 64 i32 lanes = 64 rows, and the same register group seen as i8
1780	// is 256 bytes = 64 rows x 4 columns, which is the operand shape the
1781	// instruction consumes. Everything else falls through to the generic kernel.
1782	#if defined(Q1_D4) && Q1_D4
1783	
1784	// vd[lane] += sum_{k<4} vs1[4*lane+k] * vs2[4*lane+k], int8 x int8 into i32.
1785	// GCC 14.2 has no intrinsic; inline asm is safe because GCC treats an asm block
1786	// as a vtype killer and re-emits its own vsetvli afterwards.
1787	static inline vint32m2_t q1_vd4dots_m2(vint32m2_t acc, vint8m2_t w, vint8m2_t a) {
1788	    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
1789	                 "nds.vd4dots.vv %0, %1, %2"
1790	                 : "+vr"(acc) : "vr"(w), "vr"(a) : "t0");
1791	    return acc;
1792	}
1793	
1794	// Broadcast 4 activation quants into every i32 lane. The asm barrier is load
1795	// bearing: left alone, GCC contracts "load a word, splat it" into
1796	// `vlse32.v vd, (rs1), zero`, and a stride-0 strided load is element-serial on
1797	// this core - 18x slower than lw + vmv.v.x on the same kernel. Pinning the
1798	// value in a GPR first keeps the splat a splat.
1799	static inline vint8m2_t q1_bcast_act4(uint32_t w, size_t vl32) {
1800	    asm("" : "+r"(w));
1801	    return __riscv_vreinterpret_v_i32m2_i8m2(__riscv_vmv_v_x_i32m2((int32_t) w, vl32));
1802	}
1803	
1804	static void q1_gemv_64d4_vl1024(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
1805	    const int    nb   = n / QK1_0;
1806	    const int    ng   = n / QK8_0;   // q8 groups per row
1807	    const size_t vl32 = 64;          // i32 lanes  = rows
1808	    const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns
1809	
1810	    // The dot needs 4 consecutive activation quants broadcast as one 32-bit
1811	    // element, but block_q8_0 puts qs at struct offset 2, so every other group
1812	    // is 2 mod 4 and this core faults on a misaligned 32-bit vector element
1813	    // load. Restage the quants once per call through vector BYTE ld/st (no
1814	    // alignment rule at EEW=8); the nc/64 row tiles below all reuse the copy.
1815	    int8_t * aq = (int8_t *) __builtin_alloca((size_t) ng * QK8_0);
1816	    for (int g = 0; g < ng; ++g) {
1817	        __riscv_vse8_v_i8m1(aq + (size_t) g * QK8_0, __riscv_vle8_v_i8m1(a_ptr[g].qs, QK8_0), QK8_0);
1818	    }
1819	
1820	    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);
1821	
1822	    for (int x = 0; x < nc / 64; ++x) {
1823	        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1824	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
1825	        for (int l = 0; l < nb; ++l) {
1826	            q1_prefetch_block(bx, l, nb);
1827	            const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
1828	            const uint8_t *    planes = (const uint8_t *) bx[l].qs;
1829	            vfloat32m2_t       facc   = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
1830	            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1831	                const int        g  = l * (QK1_0 / QK8_0) + k;
1832	                const uint32_t * aw = (const uint32_t *) (aq + (size_t) g * QK8_0);
1833	                vint32m2_t       acc = __riscv_vmv_v_x_i32m2(0, vl32);
1834	                for (int c = 0; c < QK8_0; c += 4) {
1835	                    const vint8m2_t a = q1_bcast_act4(aw[c / 4], vl32);
1836	                    const vbool4_t  m = __riscv_vlm_v_b4(planes + (size_t) (k * (QK8_0 / 4) + c / 4) * 32, vl8);
1837	                    const vint8m2_t w = __riscv_vmerge_vxm_i8m2(vneg1, 1, m, vl8);
1838	                    acc = q1_vd4dots_m2(acc, w, a);
1839	                }
1840	                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(a_ptr[g].d),
1841	                    __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
1842	            }
1843	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
1844	        }
1845	        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl32);
1846	    }
1847	}
