1910	static void q1_gemm_64x1_vl512(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
1911	    const int    nb   = n / QK1_0;
1912	    const int    nbq8 = n / QK8_0;
1913	    const size_t vl   = 64;
1914	    for (int y = 0; y < nr / 4; ++y) {
1915	        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
1916	        for (int x = 0; x < nc / 64; ++x) {
1917	            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1918	            for (int mh = 0; mh < 4; mh += 2) {
1919	                vfloat32m4_t sumf0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1920	                vfloat32m4_t sumf1 = sumf0;
1921	                for (int l = 0; l < nb; ++l) {
1922	                    q1_prefetch_block(bx, l, nb);
1923	                    const vfloat32m4_t dx    = q1_expand_fp16_64_m4(bx[l].d);
1924	                    vfloat32m4_t       facc0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1925	                    vfloat32m4_t       facc1 = facc0;
1926	                    for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1927	                        const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1928	                        vint16m2_t sumi0 = __riscv_vmv_v_x_i16m2(0, vl);
1929	                        vint16m2_t sumi1 = sumi0;
1930	                        for (int c = 0; c < QK8_0; ++c) {
1931	                            const vbool8_t sign = __riscv_vlm_v_b8(bx[l].qs[k * QK8_0 + c], vl);
1932	                            const int16_t  a0   = ab->qs[c * 4 + mh + 0];
1933	                            const int16_t  a1   = ab->qs[c * 4 + mh + 1];
1934	                            sumi0 = __riscv_vsub_vx_i16m2(sumi0, a0, vl);
1935	                            sumi0 = __riscv_vadd_vx_i16m2_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
1936	                            sumi1 = __riscv_vsub_vx_i16m2(sumi1, a1, vl);
1937	                            sumi1 = __riscv_vadd_vx_i16m2_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
1938	                        }
1939	                        facc0 = __riscv_vfmacc_vf_f32m4(facc0, GGML_CPU_FP16_TO_FP32(ab->d[mh + 0]),
1940	                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi0, vl), vl), vl);
1941	                        facc1 = __riscv_vfmacc_vf_f32m4(facc1, GGML_CPU_FP16_TO_FP32(ab->d[mh + 1]),
1942	                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi1, vl), vl), vl);
1943	                    }
1944	                    sumf0 = __riscv_vfmacc_vv_f32m4(sumf0, dx, facc0, vl);
1945	                    sumf1 = __riscv_vfmacc_vv_f32m4(sumf1, dx, facc1, vl);
1946	                }
1947	                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 0) * bs + (size_t) x * 64, sumf0, vl);
1948	                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 1) * bs + (size_t) x * 64, sumf1, vl);
1949	            }
