1954	static void q1_gemm_64x1_vl1024(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
1955	    const int    nb   = n / QK1_0;
1956	    const int    nbq8 = n / QK8_0;
1957	    const size_t vl   = 64;
1958	    for (int y = 0; y < nr / 4; ++y) {
1959	        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
1960	        for (int x = 0; x < nc / 64; ++x) {
1961	            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1962	            vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1963	            vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
1964	            for (int l = 0; l < nb; ++l) {
1965	                q1_prefetch_block(bx, l, nb);
1966	                const vfloat32m2_t dx    = q1_expand_fp16_64_m2(bx[l].d);
1967	                vfloat32m2_t       facc0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1968	                vfloat32m2_t       facc1 = facc0, facc2 = facc0, facc3 = facc0;
1969	                for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1970	                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1971	                    vint16m1_t sumi0 = __riscv_vmv_v_x_i16m1(0, vl);
1972	                    vint16m1_t sumi1 = sumi0, sumi2 = sumi0, sumi3 = sumi0;
1973	                    for (int c = 0; c < QK8_0; ++c) {
1974	                        const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
1975	                        const int16_t   a0 = ab->qs[c * 4 + 0], a1 = ab->qs[c * 4 + 1];
1976	                        const int16_t   a2 = ab->qs[c * 4 + 2], a3 = ab->qs[c * 4 + 3];
1977	                        sumi0 = __riscv_vsub_vx_i16m1(sumi0, a0, vl);
1978	                        sumi0 = __riscv_vadd_vx_i16m1_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
1979	                        sumi1 = __riscv_vsub_vx_i16m1(sumi1, a1, vl);
1980	                        sumi1 = __riscv_vadd_vx_i16m1_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
