// GCC 14.2 has no intrinsic; inline asm is safe because GCC treats an asm block
// as a vtype killer and re-emits its own vsetvli afterwards.
static inline vint32m2_t q1_vd4dots_m2(vint32m2_t acc, vint8m2_t w, vint8m2_t a) {
    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
                 "nds.vd4dots.vv %0, %1, %2"
                 : "+vr"(acc) : "vr"(w), "vr"(a) : "t0");
    return acc;
}

// F9, the vtype-churn fix. Four dots in ONE asm block instead of four blocks.
// GCC cannot see inside an asm block, so it must assume each one left vtype
// unknown and re-issue its own vsetvli before the next intrinsic - meaning
// every separate block costs two vsetvli, its own plus GCC's. Widening the
// block pays that once for four dots. The gemv form chains four (weight,
// activation) pairs into one accumulator; the gemm form shares one weight
// across the four output rows of the M-tile. Both are the same instruction
// with the same operands as the single-dot version, just fewer mode switches
// around them - results are unchanged. ./check-vd4dots.sh gates the ratio.
static inline vint32m2_t q1_vd4dots_x4_m2(vint32m2_t acc,
        vint8m2_t w0, vint8m2_t w1, vint8m2_t w2, vint8m2_t w3,
        vint8m2_t a0, vint8m2_t a1, vint8m2_t a2, vint8m2_t a3) {
    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
                 "nds.vd4dots.vv %0, %1, %5\n\t"
                 "nds.vd4dots.vv %0, %2, %6\n\t"
                 "nds.vd4dots.vv %0, %3, %7\n\t"
                 "nds.vd4dots.vv %0, %4, %8"
                 : "+vr"(acc)
                 : "vr"(w0), "vr"(w1), "vr"(w2), "vr"(w3),
                   "vr"(a0), "vr"(a1), "vr"(a2), "vr"(a3)
                 : "t0");
    return acc;
}

static inline void q1_vd4dots_4acc_m2(vint32m2_t * acc0, vint32m2_t * acc1,
        vint32m2_t * acc2, vint32m2_t * acc3, vint8m2_t w,
        vint8m2_t a0, vint8m2_t a1, vint8m2_t a2, vint8m2_t a3) {
    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
                 "nds.vd4dots.vv %0, %4, %5\n\t"
                 "nds.vd4dots.vv %1, %4, %6\n\t"
                 "nds.vd4dots.vv %2, %4, %7\n\t"
                 "nds.vd4dots.vv %3, %4, %8"
                 : "+vr"(*acc0), "+vr"(*acc1), "+vr"(*acc2), "+vr"(*acc3)
                 : "vr"(w), "vr"(a0), "vr"(a1), "vr"(a2), "vr"(a3)
                 : "t0");
