1830	// gemm: one weight vector against the four output rows of the M-tile
1831	static inline void q1_vd4dots_4acc_m2(vint32m2_t * acc0, vint32m2_t * acc1,
1832	        vint32m2_t * acc2, vint32m2_t * acc3, vint8m2_t w,
1833	        uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3) {
1834	    vint8m2_t s0, s1;
1835	    asm volatile(
1836	        "vsetvli t0, zero, e32, m2, ta, ma\n\t"
1837	        "vmv.v.x %[s0], %[u0]\n\t"
1838	        "vmv.v.x %[s1], %[u1]\n\t"
1839	        "nds.vd4dots.vv %[a0], %[w], %[s0]\n\t"
1840	        "nds.vd4dots.vv %[a1], %[w], %[s1]\n\t"
1841	        "vmv.v.x %[s0], %[u2]\n\t"
1842	        "vmv.v.x %[s1], %[u3]\n\t"
1843	        "nds.vd4dots.vv %[a2], %[w], %[s0]\n\t"
1844	        "nds.vd4dots.vv %[a3], %[w], %[s1]"
1845	        : [a0] "+vr" (*acc0), [a1] "+vr" (*acc1),
1846	          [a2] "+vr" (*acc2), [a3] "+vr" (*acc3),
1847	          [s0] "=&vr" (s0), [s1] "=&vr" (s1)
1848	        : [w] "vr" (w),
1849	          [u0] "r" (u0), [u1] "r" (u1), [u2] "r" (u2), [u3] "r" (u3)
1850	        : "t0");
1851	}
