1853	static void q1_gemv_64d4_vl1024(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
1854	    const int    nb   = n / QK1_0;
1855	    const int    ng   = n / QK8_0;   // q8 groups per row
1856	    const size_t vl32 = 64;          // i32 lanes  = rows
1857	    const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns
1858	
1859	    // The dot needs 4 consecutive activation quants broadcast as one 32-bit
1860	    // element, but block_q8_0 puts qs at struct offset 2, so every other group
1861	    // is 2 mod 4 and this core faults on a misaligned 32-bit vector element
1862	    // load. Restage the quants once per call through vector BYTE ld/st (no
1863	    // alignment rule at EEW=8); the nc/64 row tiles below all reuse the copy.
1864	    int8_t * aq = (int8_t *) __builtin_alloca((size_t) ng * QK8_0);
1865	    for (int g = 0; g < ng; ++g) {
1866	        __riscv_vse8_v_i8m1(aq + (size_t) g * QK8_0, __riscv_vle8_v_i8m1(a_ptr[g].qs, QK8_0), QK8_0);
1867	    }
1868	
1869	    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);
1870	
1871	    for (int x = 0; x < nc / 64; ++x) {
1872	        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1873	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
1874	        for (int l = 0; l < nb; ++l) {
1875	            q1_prefetch_block(bx, l, nb);
1876	            const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
1877	            const uint8_t *    planes = (const uint8_t *) bx[l].qs;
1878	            vfloat32m2_t       facc   = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
1879	            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1880	                const int        g  = l * (QK1_0 / QK8_0) + k;
1881	                const uint32_t * aw = (const uint32_t *) (aq + (size_t) g * QK8_0);
1882	                vint32m2_t       acc = __riscv_vmv_v_x_i32m2(0, vl32);
1883	                // 8 column quads, taken 4 at a time: all the e8 work (mask
1884	                // load + sign expand) first, then all the e32 work (broadcast
1885	                // + dot), so one vsetvli covers each half instead of one per
1886	                // step. Interleaving them is what cost 4 vsetvli per dot.
1887	                for (int q = 0; q < QK8_0 / 4; q += 4) {
1888	                    const uint8_t * p = planes + (size_t) (k * (QK8_0 / 4) + q) * 32;
1889	                    const vint8m2_t w0 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p +  0, vl8), vl8);
1890	                    const vint8m2_t w1 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 32, vl8), vl8);
1891	                    const vint8m2_t w2 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 64, vl8), vl8);
1892	                    const vint8m2_t w3 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 96, vl8), vl8);
1893	                    acc = q1_vd4dots_x4_m2(acc, w0, w1, w2, w3,
1894	                        aw[q + 0], aw[q + 1], aw[q + 2], aw[q + 3]);
1895	                }
1896	                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(a_ptr[g].d),
1897	                    __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
1898	            }
1899	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
1900	        }
1901	        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl32);
1902	    }
1903	}
